from app.state import RoveState


def score(candidate: dict, tag_weights: dict) -> float:
    """Sum of the user's weights over the candidate's tags. Arithmetic, not a model call."""
    return round(sum(tag_weights.get(tag, 0.0) for tag in candidate.get("tags", [])), 3)


def taste(state: RoveState) -> dict:
    tag_weights = state.get("taste", {}).get("tags", {})
    scored = [{**c, "score": score(c, tag_weights)} for c in state.get("candidates", [])]
    # sorted() is stable, so ties keep scout's order
    return {"ranked": sorted(scored, key=lambda c: c["score"], reverse=True)}

from app.state import RoveState

# Which budget category a candidate's cost is charged to.
CATEGORY = {"place": "activities", "event": "activities", "shop": "shopping"}


def remaining(budget: dict, category: str) -> float | None:
    """Money left in a category, or None when no allocation was set for it."""
    alloc = budget.get("alloc", {})
    if category not in alloc:
        return None
    return alloc[category] - budget.get("spent", {}).get(category, 0)


def budget(state: RoveState) -> dict:
    b = state.get("budget", {})
    warnings = list(state.get("warnings", []))

    for category, allocated in b.get("alloc", {}).items():
        spent = b.get("spent", {}).get(category, 0)
        if spent > allocated:
            warnings.append(f"overspent on {category}: ₹{spent:g} of ₹{allocated:g}")

    kept = []
    for c in state.get("ranked", []):
        left = remaining(b, CATEGORY.get(c.get("kind"), "activities"))
        if left is None or c.get("cost_inr", 0) <= left:
            kept.append(c)
    return {"ranked": kept, "warnings": warnings}

from app.state import RoveState

# Fabrics that are wrong for an activity. Linen on the Dudhsagar trek is the demo case.
UNSUITABLE = {
    "trek": {"linen", "silk", "wool"},
    "beach": {"silk", "wool"},
}
# Fabric to reach for first when it is packed.
PREFERRED = {
    "trek": "quick-dry",
    "sunset": "linen",
}


def pick_outfit(activity: str, wardrobe: list) -> dict | None:
    suitable = [w for w in wardrobe if w["fabric"] not in UNSUITABLE.get(activity, set())]
    for w in suitable:
        if w["fabric"] == PREFERRED.get(activity):
            return w
    return suitable[0] if suitable else None


def wardrobe(state: RoveState) -> dict:
    packed = state.get("wardrobe", [])
    warnings = list(state.get("warnings", []))
    if not packed:
        # nothing recorded as packed: no constraint to apply
        return {"ranked": state.get("ranked", []), "warnings": warnings}

    kept = []
    for c in state.get("ranked", []):
        outfit = pick_outfit(c.get("activity", ""), packed)
        if outfit is None:
            warnings.append(f"nothing packed suits {c['name']} ({c.get('activity')})")
            continue
        kept.append({**c, "outfit": outfit["id"]})
    return {"ranked": kept, "warnings": warnings}

import unittest

from app.nodes.taste import taste


class TasteTest(unittest.TestCase):
    def test_ranks_by_tag_overlap(self):
        state = {
            "taste": {"tags": {"sunset": 0.8, "trek": 0.3, "market": -0.5}, "ratings": []},
            "candidates": [
                {"name": "market", "tags": ["market", "food"]},
                {"name": "falls", "tags": ["trek", "waterfall"]},
                {"name": "fort", "tags": ["sunset", "fort"]},
            ],
        }
        out = taste(state)
        self.assertEqual(set(out), {"ranked"})
        self.assertEqual([c["name"] for c in out["ranked"]], ["fort", "falls", "market"])
        self.assertEqual([c["score"] for c in out["ranked"]], [0.8, 0.3, -0.5])

    def test_no_profile_keeps_scout_order(self):
        out = taste({"candidates": [{"name": "a", "tags": ["x"]}, {"name": "b", "tags": []}]})
        self.assertEqual([c["name"] for c in out["ranked"]], ["a", "b"])


if __name__ == "__main__":
    unittest.main()

import unittest

from app.nodes.budget import budget


class BudgetTest(unittest.TestCase):
    def test_drops_what_breaks_the_remaining_allocation(self):
        state = {
            "budget": {"alloc": {"activities": 4000}, "spent": {"activities": 1000}},
            "ranked": [
                {"name": "falls", "kind": "place", "cost_inr": 3500},
                {"name": "fort", "kind": "place", "cost_inr": 0},
                {"name": "walk", "kind": "event", "cost_inr": 3000},
            ],
        }
        out = budget(state)
        self.assertEqual(set(out), {"ranked", "warnings"})
        self.assertEqual([c["name"] for c in out["ranked"]], ["fort", "walk"])
        self.assertEqual(out["warnings"], [])

    def test_category_without_allocation_is_unconstrained(self):
        state = {
            "budget": {"alloc": {"activities": 100}, "spent": {}},
            "ranked": [{"name": "feni", "kind": "shop", "cost_inr": 600}],
        }
        self.assertEqual(len(budget(state)["ranked"]), 1)

    def test_warns_on_overspend(self):
        state = {"budget": {"alloc": {"food": 1000}, "spent": {"food": 1250}}, "ranked": []}
        self.assertEqual(budget(state)["warnings"], ["overspent on food: ₹1250 of ₹1000"])


if __name__ == "__main__":
    unittest.main()

import unittest

from app.nodes.wardrobe import wardrobe

LINEN = {"id": "linen-shirt", "colour": "white", "formality": "smart", "fabric": "linen"}
QUICK_DRY = {"id": "trek-tee", "colour": "black", "formality": "casual", "fabric": "quick-dry"}

FALLS = {"name": "Dudhsagar Falls", "activity": "trek"}
FORT = {"name": "Chapora Fort", "activity": "sunset"}


class WardrobeTest(unittest.TestCase):
    def test_linen_only_drops_the_trek(self):
        out = wardrobe({"wardrobe": [LINEN], "ranked": [FALLS, FORT]})
        self.assertEqual(set(out), {"ranked", "warnings"})
        self.assertEqual([c["name"] for c in out["ranked"]], ["Chapora Fort"])
        self.assertEqual(out["warnings"], ["nothing packed suits Dudhsagar Falls (trek)"])

    def test_assigns_the_right_outfit_to_each_activity(self):
        out = wardrobe({"wardrobe": [LINEN, QUICK_DRY], "ranked": [FALLS, FORT]})
        outfits = {c["name"]: c["outfit"] for c in out["ranked"]}
        self.assertEqual(outfits, {"Dudhsagar Falls": "trek-tee", "Chapora Fort": "linen-shirt"})
        self.assertEqual(out["warnings"], [])

    def test_empty_wardrobe_applies_no_constraint(self):
        out = wardrobe({"wardrobe": [], "ranked": [FALLS, FORT]})
        self.assertEqual(out["ranked"], [FALLS, FORT])


if __name__ == "__main__":
    unittest.main()

