from math import asin, cos, radians, sin, sqrt

from neatlogs import span

from app.state import RoveState

# A reel that places a venue further than this from where it really is gets refused.
MAX_REEL_MISMATCH_M = 50_000


def distance_m(lat1: float, lng1: float, lat2: float, lng2: float) -> float:
    """Great-circle distance in metres (haversine)."""
    dlat, dlng = radians(lat2 - lat1), radians(lng2 - lng1)
    a = sin(dlat / 2) ** 2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng / 2) ** 2
    return 2 * 6_371_000 * asin(sqrt(a))


def refusal(c: dict) -> str | None:
    """Why this candidate must not reach the feed, or None if it may."""
    if not c.get("exists"):
        return "venue not found"
    if not c.get("open_now"):
        return "closed right now"
    for video in c.get("videos", []):
        off_by = distance_m(c["lat"], c["lng"], video["claimed_lat"], video["claimed_lng"])
        if off_by > MAX_REEL_MISMATCH_M:
            return "not where the reel claims"
    return None


@span(kind="GUARDRAIL", name="verifier")
def verifier(state: RoveState) -> dict:
    ok, bad = [], []
    for c in state.get("ranked", []):
        reason = refusal(c)
        if reason:
            bad.append({**c, "reason": reason})
        else:
            ok.append(c)
    return {"verified": ok, "rejected": state.get("rejected", []) + bad}


def route(state: RoveState) -> str:
    if state.get("verified"):
        return "feed"
    if state.get("replans", 0) < 2:
        return "replan"
    return "give_up"

from app.state import RoveState


def feed(state: RoveState) -> dict:
    """Turn the best verified candidate into the one nudge for this run."""
    top = state["verified"][0]
    return {
        "nudge": {
            "id": top["id"],
            "name": top["name"],
            "kind": top["kind"],
            "outfit": top.get("outfit"),
            "cost_inr": top.get("cost_inr", 0),
        }
    }

import unittest

from app.nodes.verifier import route, verifier

GOOD = {"id": "a", "name": "A", "exists": True, "open_now": True, "lat": 15.5, "lng": 73.8}


class VerifierTest(unittest.TestCase):
    def test_splits_ranked_into_verified_and_rejected_with_reasons(self):
        far_reel = {"claimed_lat": 15.0, "claimed_lng": 74.3}
        state = {
            "ranked": [
                GOOD,
                {**GOOD, "id": "b", "name": "B", "exists": False},
                {**GOOD, "id": "c", "name": "C", "open_now": False},
                {**GOOD, "id": "d", "name": "D", "videos": [far_reel]},
            ]
        }
        out = verifier(state)
        self.assertEqual(set(out), {"verified", "rejected"})
        self.assertEqual([c["id"] for c in out["verified"]], ["a"])
        self.assertEqual(
            {r["id"]: r["reason"] for r in out["rejected"]},
            {"b": "venue not found", "c": "closed right now", "d": "not where the reel claims"},
        )

    def test_keeps_earlier_rejections(self):
        earlier = {"id": "x", "name": "X", "reason": "closed right now"}
        out = verifier({"ranked": [{**GOOD, "open_now": False}], "rejected": [earlier]})
        self.assertEqual([r["id"] for r in out["rejected"]], ["x", "a"])

    def test_route(self):
        self.assertEqual(route({"verified": [GOOD], "replans": 0}), "feed")
        self.assertEqual(route({"verified": [], "replans": 0}), "replan")
        self.assertEqual(route({"verified": [], "replans": 1}), "replan")
        self.assertEqual(route({"verified": [], "replans": 2}), "give_up")


if __name__ == "__main__":
    unittest.main()

